function footerMarkup(){return `<div class="footer-top"><div class="footer-identity"><a class="footer-wordmark" href="/">Imagica<span>PORTRAITS</span></a><p>We Bring Imagination Into Reality.</p></div><div><span class="footer-label">Explore</span><a href="/about/">Our story</a><a href="/gallery/">Collections</a><a href="/films/">Films</a><a href="/services/">Services</a><a href="/events/">Events</a></div><div><span class="footer-label">Your chapter</span>${['Weddings','Pre-Wedding','Portraits','Maternity'].map(c=>`<a href="/gallery/?category=${encodeURIComponent(c)}">${c}</a>`).join('')}<a href="/contact/">Contact us ↗</a></div><div class="footer-contact"><span class="footer-label">Let’s connect</span>${settings.phone?`<a href="${booking()}" target="_blank" rel="noopener">WhatsApp ↗</a><a href="tel:+${esc(settings.phone)}">+${esc(settings.phone)}</a>`:'<a href="/contact/">Book your story ↗</a>'}${settings.email?`<a href="mailto:${esc(settings.email)}">${esc(settings.email)}</a>`:''}${settings.instagram?`<a href="${esc(safeUrl(settings.instagram))}" target="_blank" rel="noopener">Instagram ↗</a>`:''}${settings.location?`<p>${esc(settings.location)}</p>`:''}</div></div><div class="footer-bottom"><span>© <span id="year">${new Date().getFullYear()}</span> Imagica Portraits.</span><span>Honest frames. Timeless feelings.</span><a href="/admin/">Studio admin ↗</a></div>`}
function renderFooter(){const f=$('#site-footer');if(f)f.innerHTML=footerMarkup()}
function home(){
 const slides=[{category:'Weddings',tag:'A celebration of love & everything in between',title:'Some moments<br>deserve <em>forever.</em>',text:'The beauty of love. The warmth of tradition. The little things that make your story unforgettable.',photo:samples[4]},{category:'Pre-Wedding',tag:'Before the vows. Beyond the ordinary.',title:'A little magic.<br>A lot of <em>you.</em>',text:'Your favourite place, your favourite person, and a story that could only be yours.',photo:samples[0]},{category:'Maternity',tag:'For the love that keeps growing',title:'The beginning<br>of <em>everything.</em>',text:'A new chapter. A beautiful anticipation. The moments you will one day tell them about.',photo:samples[2]}];
 const featured=photos.filter(p=>p.featured);const picks=(featured.length?featured:photos).slice(0,4);
 return `<div class="home-page"><div class="home-banner" aria-label="Photography highlights" aria-roledescription="carousel">${slides.map((s,i)=>`<article class="banner-frame" data-banner-frame="${i}" ${i?'hidden':''} aria-label="${i+1} of 3: ${s.category}"><img class="banner-backdrop" src="${esc(s.photo.url)}" alt="" aria-hidden="true"><img class="banner-image" src="${esc(s.photo.url)}" alt="${esc(s.photo.title)}" loading="eager" decoding="async" ${i?'fetchpriority="low"':'fetchpriority="high"'}><div class="banner-shade"></div><div class="banner-copy"><span class="eyebrow">${s.tag}</span>${i?'<h2>':'<h1>'}${s.title}${i?'</h2>':'</h1>'}<p>${s.text}</p><div class="banner-actions"><a class="button light" href="/gallery/?category=${encodeURIComponent(s.category)}">Explore the stories <span>↗</span></a><a class="text-link light" data-booking href="https://wa.me/919014337016">Book on WhatsApp ↗</a></div></div><span class="hero-edition">IMAGICA PORTRAITS / ${s.category.toUpperCase()}</span></article>`).join('')}<div class="banner-bottom"><a href="#introduction" class="scroll-cue">SCROLL TO DISCOVER <span>↓</span></a><div class="banner-controls"><button data-banner-pause aria-label="Pause slideshow" aria-pressed="false">Ⅱ</button><button data-banner-step="-1" aria-label="Previous banner">←</button><div class="banner-dots">${slides.map((s,i)=>`<button data-banner-to="${i}" aria-label="Show ${s.category} banner" aria-pressed="${!i}">${String(i+1).padStart(2,'0')}</button>`).join('')}</div><button data-banner-step="1" aria-label="Next banner">→</button></div></div></div>
 <section id="introduction" class="editorial-intro"><div class="section-index">01 / THE WAY WE SEE IT</div><div><h2>Not just photographs.<br><em>Stories that stay.</em></h2><div class="intro-columns"><p>The glance that says everything. The laughter that fills a room. The hands you never want to let go of.</p><div><p>We’re here for the moments that feel like you. With a thoughtful eye and a little imagination, we turn fleeting feelings into something you can keep.</p><a class="text-link" href="/about/">Meet Imagica Portraits ↗</a></div></div></div></section>
 <section class="selected-stories"><div class="section-title"><div><span class="eyebrow">02 / Selected stories</span><h2>Life, beautifully<br><em>unscripted.</em></h2></div><a class="text-link" href="/gallery/">View all collections ↗</a></div><div class="editorial-collection">${collectionCards.map(([category,copy,index],i)=>{const p=studioPhoto(category,index);return `<a class="collection-story story-${i}" href="/gallery/?category=${encodeURIComponent(category)}"><div class="collection-image"><img src="${esc(p.url)}" alt="${esc(p.description||p.title)}" loading="lazy"><span class="image-arrow">↗</span></div><div class="collection-caption"><span>0${i+1} / ${category}</span><h3>${copy}</h3></div></a>`}).join('')}</div></section>
 <section class="philosophy-band"><img src="/assets/msr-6500.jpg" alt="An intimate couple portrait by Imagica Portraits" loading="lazy"><div><span class="eyebrow">Our philosophy</span><h2>Real emotions.<br>Honest frames.<br><em>Timeless memories.</em></h2><p>Nothing forced. Nothing borrowed. Just the extraordinary beauty of your everyday connection.</p><a class="text-link light" href="/about/">A feeling, before a photograph ↗</a></div></section>
 <section class="services-preview"><div><span class="eyebrow">03 / What are we celebrating?</span><h2>Every chapter.<br><em>Every kind of love.</em></h2><p>From the once-in-a-lifetime to the beautifully ordinary. Thoughtful photography for the stories you want to remember.</p><a class="text-link" href="/services/">Explore our services ↗</a></div><div class="service-lines">${studioServices.slice(0,5).map(([category,title],i)=>`<a href="/services/#${category.toLowerCase().replaceAll(' ','-')}"><span>0${i+1}</span><h3>${title}</h3><span>↗</span></a>`).join('')}</div></section>
 <section class="film-teaser"><div class="film-teaser-visual"><img src="/assets/msr-6578.jpg" alt="A portrait shaped by light and shadow" loading="lazy"><span class="film-label">A DIFFERENT WAY TO REMEMBER</span></div><div><span class="eyebrow">04 / Motion & emotion</span><h2>Some feelings<br>are meant to <em>move.</em></h2><p>Step into the studio’s film collection. Stories in motion, ready to revisit when the moment has passed.</p><a class="button outline" href="/films/">Explore films ↗</a></div></section>
 ${picks.length?`<section class="frame-strip"><div class="section-title"><span class="eyebrow">The moments in between</span><a class="text-link" href="/gallery/">Through our lens ↗</a></div><div>${picks.map(p=>`<button class="photo" data-photo="${esc(p.id)}" aria-label="View ${esc(p.title)}"><img src="${esc(p.url)}" alt="${esc(p.description||p.title)}" loading="lazy"></button>`).join('')}</div></section>`:''}${settings.testimonial?`<section class="testimonial"><span class="eyebrow">A client’s words</span><blockquote>“${esc(settings.testimonial)}”</blockquote><p>${esc(settings.testimonialName)}</p></section>`:''}${editorialCTA()}</div>`;
}
function about(){return `<div class="about-page"><section class="story-opening"><div><span class="eyebrow">The people. The feeling. The photograph.</span><h1>Behind every frame,<br><em>a feeling.</em></h1><p class="lede">At Imagica Portraits, we believe photography is more than preserving how a moment looked. It’s about remembering how it felt.</p><a class="text-link" href="#our-approach">Discover our approach ↓</a></div><figure><img src="/assets/msr-4059.jpg" alt="A thoughtful studio portrait in natural patterns of light" fetchpriority="high"><figcaption>IMAGICA PORTRAITS / A PERSONAL PERSPECTIVE</figcaption></figure></section><section class="manifesto"><span class="eyebrow">Our reason why</span><h2>The photographs you love<br>are the ones you <em>feel.</em></h2><div><p>People first. Always. The relationships, rituals, and tiny gestures that make your celebration personal are what draw our eye.</p><p>We make space for you to be comfortable, for moments to unfold, and for your story to lead the way. Our imagination brings it into focus.</p></div></section><section class="studio-profile"><img src="/assets/msr-4081.jpg" alt="Creative light and colour in an Imagica portrait" loading="lazy"><div><span class="eyebrow">We Bring Imagination Into Reality.</span><h2>${settings.photographerName?esc(settings.photographerName):'A thoughtful eye.<br><em>An open heart.</em>'}</h2><p class="studio-biography">${esc(settings.studioBio||'We begin by listening. To your ideas, to the people involved, and to the things you most want to remember. Every session is a collaboration, shaped around your story.')}</p><a class="button" href="/contact/">Let’s get to know you ↗</a></div></section><section id="our-approach" class="approach"><div class="section-title"><div><span class="eyebrow">Simple, personal, considered</span><h2>Your story.<br><em>Our whole attention.</em></h2></div></div><div class="approach-grid">${[['We listen.','Tell us your story, your people, and what matters to you.'],['We imagine.','Together, we shape a vision that feels personal and honest.'],['We document.','From the big moments to the ones you almost missed.'],['You remember.','A collection of photographs to come back to, again and again.']].map(([title,copy],i)=>`<article><span>0${i+1}</span><h3>${title}</h3><p>${copy}</p></article>`).join('')}</div></section>${editorialCTA()}</div>`}
function gallery(){return `<div class="collection-page"><div class="page-head"><span class="eyebrow">The Imagica collections</span><h1>Life moves. <em>Memories stay.</em></h1><p>Love, laughter, and little things. Stories through our lens.</p></div><section class="gallery-section"><div class="gallery-toolbar"><span>Find your chapter</span><div class="filters">${['All',...cats].map(c=>`<button class="filter ${filter===c?'active':''}" data-filter="${esc(c)}" aria-pressed="${filter===c}">${c}</button>`).join('')}</div><span id="gallery-count" class="gallery-count" aria-live="polite"></span></div><div class="gallery" id="gallery-grid" aria-live="polite"></div></section>${editorialCTA()}</div>`}
function servicesPage(){return `<div class="services-page"><div class="page-head wide-head"><span class="eyebrow">Thoughtfully made. Entirely yours.</span><h1>For the moments<br>that <em>matter.</em></h1><p>Photography that meets you where your story is.<br>Tell us the occasion. We’ll take care of the feeling.</p></div><section class="service-stories">${studioServices.map(([category,title,description,fallback],i)=>{const p=studioPhoto(category,fallback);return `<article class="service-story" id="${category.toLowerCase().replaceAll(' ','-')}"><figure><img src="${esc(p.url)}" alt="${esc(p.description||p.title)}" loading="lazy"></figure><div><span class="eyebrow">0${i+1} / Made for your story</span><h2>${title}</h2><p>${description}</p><p class="service-detail">We’ll discuss the location, session plan, and photograph delivery with you before booking.</p><a class="text-link" href="${esc(enquiryLink(category))}">Enquire about ${category.toLowerCase()} ↗</a></div></article>`}).join('')}</section><section class="service-note"><span class="eyebrow">Something a little different?</span><h2>Your imagination<br>is a good <em>place to start.</em></h2><p>Have a creative project or an occasion we haven’t mentioned? Tell us what you have in mind.</p><a class="button" href="/contact/">Start a conversation ↗</a></section></div>`}
function filmsPage(){return `<div class="films-page"><div class="page-head"><span class="eyebrow">Imagica in motion</span><h1>Stories that move.<br><em>Feelings that stay.</em></h1><p>Watch our latest films and moments on Instagram.</p><a class="text-link light" href="https://www.instagram.com/imagica_portraits/" target="_blank" rel="noopener">Follow @imagica_portraits ↗</a></div><section class="reel-gallery">${(typeof instagramReels==='undefined'?[]:instagramReels).map((id,i)=>`<article class="reel-player"><iframe src="https://www.instagram.com/reel/${id}/embed/" title="Imagica Portraits film ${i+1}" loading="lazy" allow="autoplay; encrypted-media; fullscreen; picture-in-picture" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe><a href="https://www.instagram.com/reel/${id}/" target="_blank" rel="noopener">Watch film ${String(i+1).padStart(2,'0')} on Instagram ↗</a></article>`).join('')}</section></div>`}
function nativeFilmsPage(){const items=typeof studioFilms!=='undefined'?studioFilms:[];return `<div class="films-page"><div class="page-head"><span class="eyebrow">The motion collection</span><h1>More than a moment.<br><em>A feeling, in motion.</em></h1><p>Stories to watch. Moments to feel all over again.</p></div>${items.length?`<section class="film-gallery">${items.map(f=>`<figure class="film-player ${f.orientation==='landscape'?'landscape':''}"><video controls playsinline loop muted preload="metadata" poster="${esc(safeUrl(f.poster))}" aria-label="${esc(f.title)}"><source src="${esc(safeUrl(f.src))}" type="video/mp4">Your browser does not support video playback.</video><figcaption>${esc(f.title)}</figcaption></figure>`).join('')}</section>`:`<section class="film-coming"><div class="film-still"><img src="/assets/msr-6500.jpg" alt="A still photograph from the Imagica Portraits collection" loading="lazy"><span>IMAGICA / MOTION COLLECTION</span></div><div><span class="eyebrow">The next chapter</span><h2>Good stories<br>are worth <em>waiting for.</em></h2><p>Our film collection hasn’t been published yet. In the meantime, explore the moments we’ve captured in photographs.</p><a class="button light" href="/gallery/">Explore the photographs ↗</a><a class="text-link light" href="/contact/">Ask the studio about films ↗</a></div></section>`}<div class="film-endnote">REAL MOMENTS. REMEMBERED DIFFERENTLY.</div></div>`}
let stopFilmPlayback=()=>{};
function bindFilms(){stopFilmPlayback();const videos=[...document.querySelectorAll('.film-player video')];if(!videos.length)return;const reduced=typeof matchMedia==='function'&&matchMedia('(prefers-reduced-motion: reduce)').matches;const inView=new Set(),userPaused=new Set();const autoPaused=new WeakSet();const pause=v=>{if(!v.paused){autoPaused.add(v);v.pause()}};const play=v=>{if(!reduced&&!document.hidden&&!userPaused.has(v)&&v.muted)v.play().catch(()=>{})};const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){inView.add(e.target);play(e.target)}else{inView.delete(e.target);pause(e.target)}}),{threshold:.5});videos.forEach(v=>{observer.observe(v);v.onpause=()=>{if(autoPaused.has(v)){autoPaused.delete(v);return}if(!document.hidden&&inView.has(v))userPaused.add(v)};v.onplay=()=>userPaused.delete(v)});const visibility=()=>videos.forEach(v=>document.hidden?pause(v):inView.has(v)&&play(v));document.addEventListener('visibilitychange',visibility);stopFilmPlayback=()=>{observer.disconnect();document.removeEventListener('visibilitychange',visibility);videos.forEach(pause)}}
function contact(){return `<div class="contact-page"><section class="contact-opening"><div><span class="eyebrow">Every story starts with hello.</span><h1>Let’s create<br>something <em>beautiful.</em></h1><p>A date, a place, a feeling you have in mind.<br>We’d love to hear your story.</p></div><img src="/assets/msr-4699.jpg" alt="Wedding rings, photographed with attention to the smallest details" fetchpriority="high"></section><section class="contact-workspace"><aside class="contact-details"><span class="eyebrow">A conversation, not a commitment.</span><h2>Tell us what<br>you’re <em>dreaming of.</em></h2><p>Share a few details below. We’ll help you imagine what comes next.</p>${settings.phone?`<div><small>Call or WhatsApp</small><a href="tel:+${esc(settings.phone)}">+${esc(settings.phone)}</a><a class="text-link" href="${booking()}">Start on WhatsApp ↗</a></div>`:''}${settings.email?`<div><small>Email</small><a href="mailto:${esc(settings.email)}">${esc(settings.email)}</a></div>`:''}${settings.location?`<div><small>Find the studio</small><p>${esc(settings.location)}</p></div>`:''}${settings.instagram?`<div><small>Follow the stories</small><a href="${esc(safeUrl(settings.instagram))}" target="_blank" rel="noopener">Instagram ↗</a></div>`:''}${!settings.phone&&!settings.email?'<p class="contact-notice">The studio’s booking contact details are being updated. Please check back soon.</p>':''}</aside><form id="inquiry" class="inquiry-card"><span class="eyebrow">Your story, in a few details</span><div class="form-grid"><label>Full name<input name="name" required maxlength="100" autocomplete="name" placeholder="Your name"></label><label>Mobile number<input name="phone" required type="tel" maxlength="25" pattern="[+0-9 ()-]{7,25}" autocomplete="tel" placeholder="Your contact number"></label><label>Email (optional)<input name="email" type="email" maxlength="200" autocomplete="email" placeholder="you@example.com"></label><label>The occasion<select name="type">${options(new URLSearchParams(location.search).get('occasion')||'')}</select></label><label>Preferred date<input name="date" type="date" min="${new Date(Date.now()+19800000).toISOString().slice(0,10)}" required></label><label>Event location<input name="eventLocation" required maxlength="300" placeholder="City or venue"></label><label class="wide">What do you have in mind?<textarea name="message" required maxlength="2000" placeholder="Your plans, your people, your ideas…"></textarea></label></div><button class="button" type="submit">Prepare your enquiry ↗</button><p class="form-note">Opens a draft in WhatsApp for you to review and send.${settings.phone?'':' WhatsApp enquiries will be available once the studio adds its number.'}</p></form></section><section class="contact-faq"><span class="eyebrow">Before we begin</span><h2>A few things <em>to know.</em></h2>${[['What should I share in my enquiry?','Your occasion, preferred date, location, and any ideas you have. We’ll work through the finer details together.'],['Can we plan a different kind of session?','Absolutely. Tell us about your idea, from an intimate gathering to a personal creative project.'],['Is my booking confirmed when I submit?','No. The form prepares a WhatsApp message. Review and send it, then discuss availability and arrangements directly with the studio.']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</section></div>`}

let eventFilter='All';
function eventCards(list){if(!list.length)return `<div class="empty editorial-empty">${smallCamera}<h3>A new chapter is on its way.</h3><p>There are no events in this collection yet.<br>Ask us about a date or a session of your own.</p><a class="text-link" href="/contact/">Plan a session ↗</a></div>`;return `<div class="events-grid">${list.map(e=>{const date=new Date(e.date),past=date<new Date();return `<article class="event"><div class="event-visual">${e.cover_url?`<img src="${esc(safeUrl(e.cover_url))}" alt="${esc(e.title)}" loading="lazy">`:`<div class="event-cover-placeholder">${smallCamera}<span>Imagica Portraits</span></div>`}<span class="event-status">${past?'Completed':'Upcoming'}</span><div class="event-date"><strong>${date.toLocaleDateString('en-IN',{day:'2-digit',timeZone:'Asia/Kolkata'})}</strong><span>${date.toLocaleDateString('en-IN',{month:'short',timeZone:'Asia/Kolkata'})}</span></div></div><div class="event-body"><span class="eyebrow">${date.toLocaleDateString('en-IN',{year:'numeric',timeZone:'Asia/Kolkata'})} · ${date.toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Kolkata'})} IST</span><h3>${esc(e.title)}</h3><p class="event-location">⌖ ${esc(e.location)}</p><p>${esc(e.description)}</p>${e.images?.length?`<details><summary>View event photographs (${e.images.length})</summary><div class="event-thumbnails">${e.images.map(u=>`<a href="${esc(safeUrl(u))}" target="_blank" rel="noopener"><img src="${esc(safeUrl(u))}" alt="${esc(e.title)} event photograph" loading="lazy"></a>`).join('')}</div></details>`:''}<a class="text-link" href="${booking()}">Ask about this event ↗</a></div></article>`}).join('')}</div>`}
function filteredEvents(){return events.filter(e=>eventFilter==='All'||(eventFilter==='Upcoming'?new Date(e.date)>=new Date():new Date(e.date)<new Date()))}
function eventsPage(){return `<div class="events-page editorial-events"><div class="page-head"><span class="eyebrow">Gather. Celebrate. Remember.</span><h1>On the calendar.<br><em>In the making.</em></h1><p>Upcoming sessions, special occasions, and celebrations from the studio.</p></div><section class="events-section"><div class="events-toolbar"><h2>The studio <em>calendar.</em></h2><div class="filters">${['All','Upcoming','Completed'].map(c=>`<button class="filter ${c===eventFilter?'active':''}" data-event-filter="${c}">${c}</button>`).join('')}</div></div><div id="event-results">${eventCards(filteredEvents())}</div></section><section class="events-invitation cream"><span class="script">An idea of your own?</span><h2>Every occasion deserves<br><em>a beautiful memory.</em></h2><p>Tell us what you’re planning. We’ll help bring it into focus.</p><a class="button" href="/contact/">Talk about your event ↗</a></section></div>`}
function bindEventFilters(){document.querySelectorAll('[data-event-filter]').forEach(b=>b.onclick=()=>{eventFilter=b.dataset.eventFilter;$('#event-results').innerHTML=eventCards(filteredEvents());document.querySelectorAll('[data-event-filter]').forEach(x=>x.classList.toggle('active',x.dataset.eventFilter===eventFilter))})}
